    pass
# simpler: per-person block
blocks = re.findall(r'(uni:\w+)\s+a\s+uni:Person\s*;\s*uni:hasName\s+"([^"]*)"\s*;\s*uni:role\s+"([^"]*)"\s*(?:;\s*uni:teaches\s+([\w\s,]+))?(?:;\s*uni:worksIn\s+([\w\s,]+))?\s*(?:;\s*uni:isEnrolledIn\s+([\w\s,]+))?(?:;\s*uni:hasEnrollmentDate\s+"[^"]*"\^?\^?xsd:date)?\s*(?:;\s*uni:hasGraduationDate\s+"([^"]*)"\^?\^?xsd:date)?\s*\.', txt)

