            if c in courses_of_student:
                if role.get(stud) == "Student":
                    g_ = grad.get(stud)
                    if g_ is None or g_ > TODAY:
                        s.add(stud)
    return s

print("Dept enrollment (currently enrolled):")
for d in dept_uni:
